//! Markings inside an outline, and outlines filled with paint.
//!
//! `outline_markings.xodr` is generated by `scenariogeneration` (see
//! `outline_markings.py`). Its road 1 is a 60 m straight from the origin
//! heading +X, banked 0.1 rad, so the surface at `(s, t)` is
//! `(s, t cos 0.1, t sin 0.1)`.

use xodr::{
    load_file_with_provenance, Corner, Marking, Object, Point, Provenance, RoadNetwork, Shape,
    Vector,
};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/outline_markings.xodr"
);

const BANK: f32 = 0.1;

fn load() -> (RoadNetwork, Provenance) {
    load_file_with_provenance(FIXTURE).expect("import")
}

fn surface(s: f32, t: f32) -> Point {
    Point::new(s, t * BANK.cos(), t * BANK.sin())
}

/// The road's normal.
fn up() -> Vector {
    Vector::new(0.0, -BANK.sin(), BANK.cos())
}

fn named<'a>(net: &'a RoadNetwork, name: &str) -> &'a Object {
    net.objects()
        .iter()
        .find(|o| o.name == name)
        .unwrap_or_else(|| panic!("no {name}"))
}

fn outline(object: &Object) -> (&[Corner], &[Vec<Corner>]) {
    match &object.shape {
        Shape::Outline { corners, holes, .. } => (corners, holes),
        other => panic!("{} is not an outline: {other:?}", object.name),
    }
}

fn assert_near(got: Point, want: Point, what: &str) {
    assert!(
        (got - want).length() < 1e-4,
        "{what}: got {got:?}, expected {want:?}"
    );
}

/// The middle of each end of each piece of `marking`, in order.
fn ends(marking: &Marking) -> Vec<(Point, Point)> {
    marking
        .pieces
        .iter()
        .map(|[a, b, c, d]| (a.lerp(*d, 0.5), b.lerp(*c, 0.5)))
        .collect()
}

fn assert_ends(got: Vec<(Point, Point)>, want: &[(Point, Point)], what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: {got:?}");
    for ((a, b), (want_a, want_b)) in got.into_iter().zip(want) {
        assert_near(a, *want_a, &format!("{what} start"));
        assert_near(b, *want_b, &format!("{what} end"));
    }
}

/// That `corners` are the road stations `at`, raised `raise` along the
/// road's normal, each `height` tall straight up.
fn assert_corners(corners: &[Corner], at: &[(f32, f32)], raise: f32, height: f32, what: &str) {
    assert_eq!(corners.len(), at.len(), "{what}");
    for (c, &(s, t)) in corners.iter().zip(at) {
        let base = surface(s, t) + up() * raise;
        assert_near(c.base, base, &format!("{what} ({s}, {t}) base"));
        assert_near(
            c.top,
            base + Vector::Z * height,
            &format!("{what} ({s}, {t}) top"),
        );
    }
}

fn rectangle(s0: f32, s1: f32, t0: f32, t1: f32) -> [(f32, f32); 4] {
    [(s0, t0), (s1, t0), (s1, t1), (s0, t1)]
}

#[test]
fn a_marking_inside_an_outline_runs_along_the_corners_it_names() {
    let (net, _) = load();
    let bay = named(&net, "Bay");
    let [solid, dashed] = &bay.markings[..] else {
        panic!("two markings: {:?}", bay.markings);
    };
    let at = |s, t| surface(s, t) + up() * 0.01;
    assert_ends(ends(solid), &[(at(5.0, -5.0), at(5.0, -1.0))], "solid");
    let want =
        [(0.0, 1.0), (1.5, 2.5), (3.0, 4.0)].map(|(a, b)| (at(10.0, -1.0 - a), at(10.0, -1.0 - b)));
    assert_ends(ends(dashed), &want, "dash");
}

#[test]
fn a_paint_area_lies_flat_just_off_the_road() {
    let (net, prov) = load();
    let arrow = named(&net, "Arrow");
    let (corners, holes) = outline(arrow);
    assert_corners(
        corners,
        &rectangle(20.0, 26.0, 1.0, 2.0),
        0.005,
        0.0,
        "area",
    );
    let [hole] = holes else {
        panic!("one hole: {holes:?}");
    };
    assert_corners(hole, &rectangle(22.0, 24.0, 1.25, 1.75), 0.005, 0.0, "hole");
    let fill = &prov.objects[arrow.id.0].fill_type;
    assert_eq!(fill, "paint");
}

#[test]
fn a_marking_inside_an_outline_naming_a_corner_of_another_is_skipped() {
    let (net, _) = load();
    let arrow = named(&net, "Arrow");
    let [edge] = &arrow.markings[..] else {
        panic!("one marking: {:?}", arrow.markings);
    };
    let at = |s, t| surface(s, t) + up() * 0.01;
    assert_ends(ends(edge), &[(at(20.0, 1.0), at(26.0, 1.0))], "edge");
}

#[test]
fn an_outline_of_another_fill_keeps_its_height_and_its_markings() {
    let (net, _) = load();
    let island = named(&net, "Island");
    let (corners, _) = outline(island);
    let origin = surface(30.0, -3.0);
    for (c, (u, v)) in corners
        .iter()
        .zip([(0.0, 0.0), (4.0, 0.0), (4.0, 2.0), (0.0, 2.0)])
    {
        let base = origin + Vector::new(u, v, 0.0);
        assert_near(c.base, base, "island base");
        assert_near(c.top, base + Vector::Z * 0.15, "island top");
    }
    let [edge] = &island.markings[..] else {
        panic!("one marking: {:?}", island.markings);
    };
    let lift = Vector::Z * 0.01;
    assert_eq!(
        ends(edge),
        [(origin + lift, origin + Vector::X * 4.0 + lift)]
    );
}

#[test]
fn a_border_does_not_cut_back_a_paint_area() {
    let (net, _) = load();
    let patch = named(&net, "Patch");
    let (corners, _) = outline(patch);
    assert_corners(
        corners,
        &rectangle(40.0, 44.0, -1.0, -2.0),
        0.005,
        0.0,
        "patch",
    );
    assert_eq!(patch.borders.len(), 1);
}

#[test]
fn an_open_outline_of_paint_keeps_its_height() {
    let (net, _) = load();
    let (corners, _) = outline(named(&net, "Stripe"));
    assert_corners(corners, &[(50.0, 2.5), (55.0, 2.5)], 0.0, 0.1, "stripe");
}

#[test]
fn markings_inside_an_outline_come_before_those_under_its_object() {
    let (net, _) = load();
    let kerb = named(&net, "Kerb");
    let at = |s, t| surface(s, t) + up() * 0.01;
    let [inside, under] = &kerb.markings[..] else {
        panic!("two markings: {:?}", kerb.markings);
    };
    assert_ends(ends(inside), &[(at(50.0, -4.0), at(50.0, -3.0))], "inside");
    assert_ends(ends(under), &[(at(55.0, -3.0), at(55.0, -4.0))], "under");
}
